export interface InferenceService {
  /**
   * Generate attaches the caller to a session's generation job.
   *   - session unknown            -> start a job, stream from token 0
   *   - resume_from_token >= head  -> replay the journal from that index, then
   *                                   stream live tokens from the same job
   *   - resume_from_token < head   -> FAILED_PRECONDITION with the first
   *                                   retained index in trailing metadata. The
   *                                   client must resync rather than silently
   *                                   accept a gap.
   */
  Generate(request: GenerateRequest): Observable<GenerateResponse>;
  /**
   * Ack records the client's confirmed watermark for a session. The server
   * uses it to trim journaled tokens the client no longer needs and to answer
   * state-recovery queries (a client that lost its local cursor can learn the
   * last index it confirmed).
   */
  Ack(request: AckRequest): Promise<AckResponse>;
  /**
   * Cancel ends a session's generation job and frees the upstream inference.
   * A dropped call is a detach, not a cancel: only this stops the model.
   * Idempotent — cancelling a completed or unknown session is not an error.
   */
  Cancel(request: CancelRequest): Promise<CancelResponse>;
}

